INSERT INTO t_mail_template (template_id, name, category, revision, published_version, has_draft, content) VALUES (
    'auth.sign_in_code',
    '登录验证码',
    'verification',
    1,
    1,
    FALSE,
    $template${
    "en-US": {
        "html": "<div\n  style=\"margin:0;padding:28px 16px;background:#eef2f6;font-family:-apple-system,BlinkMacSystemFont,Arial,sans-serif\">\n  <table role=\"presentation\"\n    style=\"width:100%;max-width:560px;margin:auto;border-spacing:0;background:#fff;border-radius:12px;border-top:5px solid #2563eb\">\n    <tbody>\n      <tr>\n        <td style=\"padding:30px 32px 32px\">\n          <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\"\n            style=\"border-collapse:collapse;margin:0 0 27px\">\n            <tbody>\n              <tr>\n                <td style=\"vertical-align:middle;padding:0 10px 0 0\"><img\n                    src=\"data:image/png;base64,\"\n                    width=\"36\" height=\"36\" alt=\"{{ (fromJSON .Computed.brand).title }}\" style=\"display:block;border:0\"></td>\n                <td\n                  style=\"vertical-align:middle;color:#0f172a;font-size:18px;font-weight:700;line-height:1.2\">\n                  {{ (fromJSON .Computed.brand).title }}</td>\n              </tr>\n            </tbody>\n          </table>\n          <h1\n            style=\"font-size:25px;line-height:1.4;margin:0 0 17px;letter-spacing:-0.4px;color:#0f172a\">\n            Sign-in code</h1>\n          <p\n            style=\"font-size:15px;line-height:1.8;color:#475569;margin:0 0 20px;overflow-wrap:anywhere\">\n            You are signing in to account <strong\n              style=\"font-weight:650;color:#0f172a\">\u007b\u007baccount\u007d\u007d</strong>.</p>\n          <div\n            style=\"background:#eff6ff;border-radius:8px;text-align:center;padding:17px 12px 19px;margin-top:22px\">\n            <div\n              style=\"font-family:Arial,sans-serif;font-size:36px;letter-spacing:9px;padding-left:9px;color:#1d4ed8;font-weight:700;line-height:1.35\">\n              \u007b\u007bcode\u007d\u007d\n            </div>\n          </div>\n          <p style=\"font-size:12px;color:#64748b;margin:10px 0 12px;line-height:1.8\">Valid until:\n            \u007b\u007bexpires_at\u007d\u007d</p>\n          <div style=\"border-top:1px solid #e2e8f0;margin-top:24px;padding-top:18px\"\n            data-section=\"safety-footer\">\n            <h2 style=\"margin:0 0 5px;font-size:14px;line-height:1.6;color:#1d4ed8;font-weight:650\">\n              If this was not you</h2>\n            <p style=\"font-size:13px;color:#475569;margin:0;line-height:1.8\">You can ignore this\n              email.</p>\n          </div>\n        </td>\n      </tr>\n    </tbody>\n  </table>\n</div>\n",
        "text": "{{ (fromJSON .Computed.brand).title }}\n\nSign-in code\n\nYou are signing in to account \u007b\u007baccount\u007d\u007d.\n\n\u007b\u007bcode\u007d\u007d\n\nValid until: \u007b\u007bexpires_at\u007d\u007d\n\nIf this was not you\n\nYou can ignore this email.",
        "subject": "Sign-in code",
        "preview_values": {
            "code": "482916",
            "account": "ex***",
            "expires_at": "2026-11-13 18:10:00"
        }
    },
    "zh-CN": {
        "html": "<div\n  style=\"margin:0;padding:28px 16px;background:#eef2f6;font-family:-apple-system,BlinkMacSystemFont,Arial,sans-serif\">\n  <table role=\"presentation\"\n    style=\"width:100%;max-width:560px;margin:auto;border-spacing:0;background:#fff;border-radius:12px;border-top:5px solid #2563eb\">\n    <tbody>\n      <tr>\n        <td style=\"padding:30px 32px 32px\">\n          <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\"\n            style=\"border-collapse:collapse;margin:0 0 27px\">\n            <tbody>\n              <tr>\n                <td style=\"vertical-align:middle;padding:0 10px 0 0\"><img\n                    src=\"data:image/png;base64,\"\n                    width=\"36\" height=\"36\" alt=\"{{ (fromJSON .Computed.brand).title }}\" style=\"display:block;border:0\"></td>\n                <td\n                  style=\"vertical-align:middle;color:#0f172a;font-size:18px;font-weight:700;line-height:1.2\">\n                  {{ (fromJSON .Computed.brand).title }}</td>\n              </tr>\n            </tbody>\n          </table>\n          <h1\n            style=\"font-size:25px;line-height:1.4;margin:0 0 17px;letter-spacing:-0.4px;color:#0f172a\">\n            登录验证码</h1>\n          <p\n            style=\"font-size:15px;line-height:1.8;color:#475569;margin:0 0 20px;overflow-wrap:anywhere\">\n            你正在登录账号 <strong style=\"font-weight:650;color:#0f172a\">\u007b\u007baccount\u007d\u007d</strong>。</p>\n          <div\n            style=\"background:#eff6ff;border-radius:8px;text-align:center;padding:17px 12px 19px;margin-top:22px\">\n            <div\n              style=\"font-family:Arial,sans-serif;font-size:36px;letter-spacing:9px;padding-left:9px;color:#1d4ed8;font-weight:700;line-height:1.35\">\n              \u007b\u007bcode\u007d\u007d\n            </div>\n          </div>\n          <p style=\"font-size:12px;color:#64748b;margin:10px 0 12px;line-height:1.8\">\n            有效期至：\u007b\u007bexpires_at\u007d\u007d</p>\n          <div style=\"border-top:1px solid #e2e8f0;margin-top:24px;padding-top:18px\"\n            data-section=\"safety-footer\">\n            <h2 style=\"margin:0 0 5px;font-size:14px;line-height:1.6;color:#1d4ed8;font-weight:650\">\n              如非本人操作</h2>\n            <p style=\"font-size:13px;color:#475569;margin:0;line-height:1.8\">请忽略此邮件。</p>\n          </div>\n        </td>\n      </tr>\n    </tbody>\n  </table>\n</div>\n",
        "text": "{{ (fromJSON .Computed.brand).title }}\n\n登录验证码\n\n你正在登录账号 \u007b\u007baccount\u007d\u007d。\n\n\u007b\u007bcode\u007d\u007d\n\n有效期至：\u007b\u007bexpires_at\u007d\u007d\n\n如非本人操作\n\n请忽略此邮件。",
        "subject": "登录验证码",
        "preview_values": {
            "code": "482916",
            "account": "ex***",
            "expires_at": "2026-11-13 18:10:00"
        }
    }
}$template$::JSONB
);

