INSERT INTO t_mail_template (template_id, name, category, revision, published_version, has_draft, content) VALUES (
    'auth.sensitive_operation_code',
    '敏感操作验证码',
    'verification',
    1,
    1,
    FALSE,
    $template${
    "en-US": {
        "html": "<div\n  style=\"margin:0;padding:28px 16px;background:#eef2f6;font-family:-apple-system,BlinkMacSystemFont,Arial,sans-serif\">\n  <table role=\"presentation\"\n    style=\"width:100%;max-width:560px;margin:auto;border-spacing:0;background:#fff;border-radius:12px;border-top:5px solid #1d4ed8\">\n    <tr>\n      <td style=\"padding:30px 32px 32px\">\n        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\"\n          style=\"border-collapse:collapse;margin:0 0 27px\">\n          <tbody>\n            <tr>\n              <td style=\"vertical-align:middle;padding:0 10px 0 0\"><img\n                  src=\"data:image/png;base64,\"\n                  width=\"36\" height=\"36\" alt=\"{{ (fromJSON .Computed.brand).title }}\" style=\"display:block;border:0\"></td>\n              <td\n                style=\"vertical-align:middle;color:#0f172a;font-size:18px;font-weight:700;line-height:1.2\">\n                {{ (fromJSON .Computed.brand).title }}</td>\n            </tr>\n          </tbody>\n        </table>\n        <h1\n          style=\"font-size:25px;line-height:1.4;margin:0 0 17px;letter-spacing:-0.4px;color:#0f172a;font-weight:700\">\n          Sensitive operation code</h1>\n        <p style=\"margin:0;font-size:15px;line-height:1.8;color:#475569;overflow-wrap:anywhere\">\n          <span>Your account </span><strong\n            style=\"font-weight:650;color:#0f172a\">\u007b\u007baccount\u007d\u007d</strong><span> is performing a\n            sensitive operation that requires authorization. Authorization is valid for\n            \u007b\u007bauthorization_duration\u007d\u007d.</span>\n        </p>\n        <div\n          style=\"margin:22px 0 0;padding:17px 12px 19px;background:#eff6ff;border-radius:8px;text-align:center\">\n          <div\n            style=\"font-family:Arial,sans-serif;font-size:36px;line-height:1.35;letter-spacing:9px;padding-left:9px;font-weight:700;color:#1d4ed8\">\n            \u007b\u007bcode\u007d\u007d\n          </div>\n        </div>\n        <p style=\"margin:10px 0 12px;font-size:12px;line-height:1.8;color:#64748b;text-align:left\">\n          <span>Valid until: </span><span>\u007b\u007bexpires_at\u007d\u007d</span>\n        </p>\n        <div style=\"border-top:1px solid #e2e8f0;margin-top:24px;padding-top:18px\"\n          data-section=\"safety-footer\">\n          <h2 style=\"margin:0 0 5px;font-size:14px;line-height:1.6;color:#92400e;font-weight:650\">If\n            this was not you</h2>\n          <p style=\"font-size:13px;color:#475569;margin:0;line-height:1.8\">Please ignore this email.\n          </p>\n        </div>\n      </td>\n    </tr>\n  </table>\n</div>\n",
        "text": "{{ (fromJSON .Computed.brand).title }}\n\nSensitive operation code\n\nYour account \u007b\u007baccount\u007d\u007d is performing a sensitive operation that requires authorization. Authorization is valid for \u007b\u007bauthorization_duration\u007d\u007d.\n\n\u007b\u007bcode\u007d\u007d\n\nValid until: \u007b\u007bexpires_at\u007d\u007d\n\nIf this was not you\n\nPlease ignore this email.",
        "subject": "[Security verification] Sensitive operation code",
        "preview_values": {
            "code": "482916",
            "account": "ex***",
            "expires_at": "2026-11-13 18:10:00",
            "authorization_duration": "10 minutes"
        }
    },
    "zh-CN": {
        "html": "<div\n  style=\"margin:0;padding:28px 16px;background:#eef2f6;font-family:-apple-system,BlinkMacSystemFont,Arial,sans-serif\">\n  <table role=\"presentation\"\n    style=\"width:100%;max-width:560px;margin:auto;border-spacing:0;background:#fff;border-radius:12px;border-top:5px solid #1d4ed8\">\n    <tr>\n      <td style=\"padding:30px 32px 32px\">\n        <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\"\n          style=\"border-collapse:collapse;margin:0 0 27px\">\n          <tbody>\n            <tr>\n              <td style=\"vertical-align:middle;padding:0 10px 0 0\"><img\n                  src=\"data:image/png;base64,\"\n                  width=\"36\" height=\"36\" alt=\"{{ (fromJSON .Computed.brand).title }}\" style=\"display:block;border:0\"></td>\n              <td\n                style=\"vertical-align:middle;color:#0f172a;font-size:18px;font-weight:700;line-height:1.2\">\n                {{ (fromJSON .Computed.brand).title }}</td>\n            </tr>\n          </tbody>\n        </table>\n        <h1\n          style=\"font-size:25px;line-height:1.4;margin:0 0 17px;letter-spacing:-0.4px;color:#0f172a;font-weight:700\">\n          敏感操作验证码</h1>\n        <p style=\"margin:0;font-size:15px;line-height:1.8;color:#475569;overflow-wrap:anywhere\">\n          <span>你的账号 </span><strong style=\"font-weight:650;color:#0f172a\">\u007b\u007baccount\u007d\u007d</strong><span>\n            正在进行敏感操作，需要授权，授权有效期 \u007b\u007bauthorization_duration\u007d\u007d。</span>\n        </p>\n        <div\n          style=\"margin:22px 0 0;padding:17px 12px 19px;background:#eff6ff;border-radius:8px;text-align:center\">\n          <div\n            style=\"font-family:Arial,sans-serif;font-size:36px;line-height:1.35;letter-spacing:9px;padding-left:9px;font-weight:700;color:#1d4ed8\">\n            \u007b\u007bcode\u007d\u007d\n          </div>\n        </div>\n        <p style=\"margin:10px 0 12px;font-size:12px;line-height:1.8;color:#64748b;text-align:left\">\n          <span>有效期至：</span><span>\u007b\u007bexpires_at\u007d\u007d</span>\n        </p>\n        <div style=\"border-top:1px solid #e2e8f0;margin-top:24px;padding-top:18px\"\n          data-section=\"safety-footer\">\n          <h2 style=\"margin:0 0 5px;font-size:14px;line-height:1.6;color:#92400e;font-weight:650\">\n            如非本人操作</h2>\n          <p style=\"font-size:13px;color:#475569;margin:0;line-height:1.8\">请忽略此邮件。</p>\n        </div>\n      </td>\n    </tr>\n  </table>\n</div>\n",
        "text": "{{ (fromJSON .Computed.brand).title }}\n\n敏感操作验证码\n\n你的账号 \u007b\u007baccount\u007d\u007d 正在进行敏感操作，需要授权，授权有效期 \u007b\u007bauthorization_duration\u007d\u007d。\n\n\u007b\u007bcode\u007d\u007d\n\n有效期至：\u007b\u007bexpires_at\u007d\u007d\n\n如非本人操作\n\n请忽略此邮件。",
        "subject": "【安全验证】敏感操作验证码",
        "preview_values": {
            "code": "482916",
            "account": "ex***",
            "expires_at": "2026-11-13 18:10:00",
            "authorization_duration": "10 分钟"
        }
    }
}$template$::JSONB
