    "en-US": {
        "html": "<div\n  style=\"margin:0;padding:28px 16px;background:#eef2f6;font-family:-apple-system,BlinkMacSystemFont,Arial,sans-serif\">\n  <table role=\"presentation\"\n    style=\"width:100%;max-width:560px;margin:auto;border-spacing:0;background:#fff;border-radius:12px;border-top:5px solid #d97706\">\n    <tbody>\n      <tr>\n        <td style=\"padding:30px 32px 32px\">\n          <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\"\n            style=\"border-collapse:collapse;margin:0 0 27px\">\n            <tbody>\n              <tr>\n                <td style=\"vertical-align:middle;padding:0 10px 0 0\"><img\n                    src=\"data:image/png;base64,\"\n                    width=\"36\" height=\"36\" alt=\"{{ (fromJSON .Computed.brand).title }}\" style=\"display:block;border:0\"></td>\n                <td\n                  style=\"vertical-align:middle;color:#0f172a;font-size:18px;font-weight:700;line-height:1.2\">\n                  {{ (fromJSON .Computed.brand).title }}</td>\n              </tr>\n            </tbody>\n          </table>\n          <p style=\"margin:0 0 12px;font-size:13px;font-weight:650;line-height:1.6;color:#92400e\">\n            <span aria-hidden=\"true\">⚠</span> Security alert\n          </p>\n          <h1\n            style=\"font-size:25px;line-height:1.4;margin:0 0 17px;letter-spacing:-0.4px;color:#0f172a\">\n            Sensitive operation notification</h1>\n          <p\n            style=\"font-size:15px;line-height:1.8;color:#475569;margin:0 0 20px;overflow-wrap:anywhere\">\n            Your account <strong style=\"font-weight:650;color:#0f172a\">\u007b\u007baccount\u007d\u007d</strong> has\n            recently performed several sensitive operations:</p>\n          <div\n            style=\"background:#fffbeb;border-left:4px solid #d97706;padding:16px 18px;margin:22px 0\">\n            <div data-section=\"activity-period\"\n              style=\"margin:0 0 14px;font-size:13px;line-height:1.8;color:#92400e\">\n              <div style=\"font-weight:700;margin-bottom:4px\">Activity period</div>\n              <div>Start time: <span style=\"color:#78350f\">\u007b\u007bactivity_started_at\u007d\u007d</span></div>\n              <div>End time: <span style=\"color:#78350f\">\u007b\u007bactivity_ended_at\u007d\u007d</span></div>\n            </div>\n            <div\n              style=\"font-size:16px;line-height:1.75;color:#78350f;font-weight:600;font-size:18px;font-weight:700\">\n              <span style=\"white-space:pre-line\">\u007b\u007bactivity_summary\u007d\u007d</span>\n            </div>\n          </div>\n          <p style=\"margin:24px 0 0\"><a\n              style=\"display:inline-block;background:#92400e;color:#fff;text-decoration:none;font-size:14px;font-weight:650;padding:12px 24px;border-radius:6px;line-height:1.5\"\n              href=\"\u007b\u007baudit_url\u007d\u007d\" target=\"_blank\" rel=\"noopener noreferrer\">View activity logs</a>\n          </p>\n          <div style=\"margin-top:26px;padding-top:17px\">\n            <p style=\"font-size:12px;color:#64748b;margin:0 0 7px;line-height:1.8\">If the button\n              does not work, copy the link into your browser:</p>\n            <p\n              style=\"font-size:12px;line-height:1.8;color:#475569;word-break:break-all;overflow-wrap:anywhere;margin:0\">\n              \u007b\u007baudit_url\u007d\u007d\n            </p>\n          </div>\n          <div style=\"border-top:1px solid #e2e8f0;margin-top:24px;padding-top:18px\"\n            data-section=\"safety-footer\">\n            <h2 style=\"margin:0 0 5px;font-size:14px;line-height:1.6;color:#92400e;font-weight:650\">\n              If this was not you</h2>\n            <p style=\"font-size:13px;color:#475569;margin:0;line-height:1.8\">Please review the\n              activity logs or contact your administrator.</p>\n          </div>\n        </td>\n      </tr>\n    </tbody>\n  </table>\n</div>\n",
        "text": "{{ (fromJSON .Computed.brand).title }}\n\n⚠ Security alert\n\nSensitive operation notification\n\nYour account \u007b\u007baccount\u007d\u007d\nhas recently performed several sensitive operations:\n\nActivity period\n\nStart time: \u007b\u007bactivity_started_at\u007d\u007d\n\nEnd time: \u007b\u007bactivity_ended_at\u007d\u007d\n\n\u007b\u007bactivity_summary\u007d\u007d\n\nView activity logs\n\nIf the button does not work, copy the link into your browser:\n\n\u007b\u007baudit_url\u007d\u007d\n\nIf this was not you\n\nPlease review the activity logs or contact your administrator.",
        "subject": "[Security alert] Sensitive operation notification",
        "preview_values": {
            "account": "ex***",
            "audit_url": "http://127.0.0.1/",
